INSERT INTO feature VALUES('width-arithmetic','types','Arithmetic on a width that stops at the end of its range','sized-integers','partial','ordinary',NULL,'An operation of a theory with no input at the carrier passes no continuation. Its clause abandons the continuation, then gives its body, on both tiers. The abandonment gives up the frames in place, so the operation copies no frame and allocates no word. `std.overflow` states `Overflow.Eff` with one such operation, and a reason that names the operation and its cause. A scope at the site gives the reason in the place of the answer. The plain operators on a width do not perform it yet, and the library has no handler for each answer type.','surface-lowering-base surface-lowering-capability runtime-emitter','corpus/ledger/features/width-arithmetic.gandr corpus/model/drop/halted.gandr corpus/pathological/drop/halted.gandr crates/surface-lowering-base/src/lower/capability/theory/tests.rs crates/runtime-emitter/src/lower.rs::an_abandoning_clause_copies_no_frame_and_allocates_no_word_7968','corpus/ledger/features/width-arithmetic.gandr','#8156 #8158 #8159 #8160 #8167');
